-- Starter assets are shared; clients may read them, but only upload/delete under their own uid folder.
DROP POLICY IF EXISTS "Users can view own vocabulary images" ON storage.objects;
CREATE POLICY "Users can view own or starter vocabulary images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'vocabulary-images' AND ((storage.foldername(name))[1] = (SELECT auth.uid())::text OR (storage.foldername(name))[1] = 'default-vocabulary'));

