peech":"noun","meaning":"tóc","category":"Body","status":"learning","ipa":"/her/","image_path":"default-vocabulary/body/hair.jpg"},{"word":"head","type":"word","part_of_speech":"noun","meaning":"đầu","category":"Body","status":"learning","ipa":"/hed/","image_path":"default-vocabulary/body/head.jpg"},{"word":"forehead","type":"word","part_of_speech":"noun","meaning":"trán","category":"Body","status":"learning","ipa":"/ˈfɔːr.ɪd/","image_path":"default-vocabulary/body/forehead.jpg"},{"word":"face","type":"word","part_of_speech":"noun","meaning":"mặt","category":"Body","status":"learning","ipa":"/feɪs/","image_path":"default-vocabulary/body/face.jpg"},{"word":"eye","type":"word","part_of_speech":"noun","meaning":"mắt","category":"Body","status":"learning","ipa":"/aɪ/","image_path":"default-vocabulary/body/eye.jpg"},{"word":"cheek","type":"word","part_of_speech":"noun","meaning":"má","category":"Body","status":"learning","ipa":"/tʃiːk/","image_path":"default-vocabulary/body/cheek.jpg"},{"word":"ear","type":"word","part_of_speech":"noun","meaning":"lỗ tai","category":"Body","status":"learning","ipa":"/ɪər/","image_path":"default-vocabulary/body/ear.jpg"},{"word":"nose","type":"word","part_of_speech":"noun","meaning":"mũi","category":"Body","status":"learning","ipa":"/nəʊz/","image_path":"default-vocabulary/body/nose.jpg"},{"word":"mouth","type":"word","part_of_speech":"noun","meaning":"miệng","category":"Body","status":"learning","ipa":"/maʊθ/","image_path":"default-vocabulary/body/mouth.jpg"},{"word":"tongue","type":"word","part_of_speech":"noun","meaning":"lưỡi","category":"Body","status":"learning","ipa":"/tʌŋ/","image_path":"default-vocabulary/body/tongue.jpg"},{"word":"neck","type":"word","part_of_speech":"noun","meaning":"cổ","category":"Body","status":"learning","ipa":"/nek/","image_path":"default-vocabulary/body/neck.jpg"},{"word":"chin","type":"word","part_of_speech":"noun","meaning":"cằm","category":"Body","status":"learning","ipa":"/ʧɪn/","image_path":"default-vocabulary/body/chin.jpg"},{"word":"shoulder","type":"word","part_of_speech":"noun","meaning":"vai","category":"Body","status":"learning","ipa":"/ˈʃəʊl.dər/","image_path":"default-vocabulary/body/shoulder.jpg"},{"word":"back","type":"word","part_of_speech":"noun","meaning":"lưng","category":"Body","status":"learning","ipa":"/bæk/","image_path":"default-vocabulary/body/back.jpg"},{"word":"arm","type":"word","part_of_speech":"noun","meaning":"cánh tay","category":"Body","status":"learning","ipa":"/ɑːm/","image_path":"default-vocabulary/body/arm.jpg"},{"word":"hand","type":"word","part_of_speech":"noun","meaning":"bàn tay","category":"Body","status":"learning","ipa":"/hænd/","image_path":"default-vocabulary/body/hand.jpg"},{"word":"finger","type":"word","part_of_speech":"noun","meaning":"ngón tay","category":"Body","status":"learning","ipa":"/ˈfɪŋ.ɡər/","image_path":"default-vocabulary/body/finger.jpg"},{"word":"thigh","type":"word","part_of_speech":"noun","meaning":"đùi","category":"Body","status":"learning","ipa":"/θaɪ/","image_path":"default-vocabulary/body/thigh.jpg"},{"word":"knee","type":"word","part_of_speech":"noun","meaning":"đầu gối","category":"Body","status":"learning","ipa":"/niː/","image_path":"default-vocabulary/body/knee.jpg"},{"word":"leg","type":"word","part_of_speech":"noun","meaning":"chân","category":"Body","status":"learning","ipa":"/leɡ/","image_path":"default-vocabulary/body/leg.jpg"},{"word":"foot","type":"word","part_of_speech":"noun","meaning":"bàn chân","category":"Body","status":"learning","ipa":"/fʊt/","image_path":"default-vocabulary/body/foot.jpg"},{"word":"toe","type":"word","part_of_speech":"noun","meaning":"ngón chân","category":"Body","status":"learning","ipa":"/təʊ/","image_path":"default-vocabulary/body/toe.jpg"},{"word":"waist","type":"word","part_of_speech":"noun","meaning":"eo","category":"Body","status":"learning","ipa":"/weɪst/","image_path":"default-vocabulary/body/waist.jpg"},{"word":"elbow","type":"word","part_of_speech":"noun","meaning":"khuỷu tay","category":"Body","status":"learning","ipa":"/ˈel.bəʊ/","image_path":"default-vocabulary/body/elbow.jpg"},{"word":"ankle","type":"word","part_of_speech":"noun","meaning":"mắt cá chân","category":"Body","status":"learning","ipa":"/ˈæŋ.kəl/","image_path":"default-vocabulary/body/ankle.jpg"}]'::jsonb;
  v_item jsonb;
  v_word_id uuid;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'A user ID is required to seed default vocabulary.'; END IF;
  INSERT INTO public.vocabulary_categories (user_id, name, color, is_default) VALUES
    (p_user_id, 'Actions', 'violet', false), (p_user_id, 'Animals', 'orange', false),
    (p_user_id, 'Family', 'rose', false), (p_user_id, 'Body', 'blue', false),
    (p_user_id, 'Supplies', 'violet', false)
  ON CONFLICT DO NOTHING;

  -- Normalize legacy starter category names to the current default category list.
  UPDATE public.vocabulary_words SET category = 'Body'
  WHERE user_id = p_user_id AND category = 'Body Parts';
  DELETE FROM public.vocabulary_categories
  WHERE user_id = p_user_id AND name = 'Body Parts' AND NOT is_default;
  UPDATE public.vocabulary_words SET category = 'Supplies'
  WHERE user_id = p_user_id AND category = 'School Supplies';
  DELETE FROM public.vocabulary_categories
  WHERE user_id = p_user_id AND name = 'School Supplies' AND NOT is_default;
  FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_items) AS items(value) LOOP
    IF EXISTS (SELECT 1 FROM public.vocabulary_words AS words WHERE words.user_id = p_user_id AND pg_catalog.lower(words.word) = pg_catalog.lower(v_item->>'word')) THEN CONTINUE; END IF;
    INSERT INTO public.vocabulary_words (user_id, word, meaning, category, status, type, ipa, image_path)
    VALUES (p_user_id, v_item->>'word', v_item->>'meaning', v_item->>'category', COALESCE(NULLIF(v_item->>'status', ''), 'learning'), COALESCE(NULLIF(v_item->>'type', ''), 'word'), NULLIF(v_item->>'ipa', ''), v_item->>'image_path')
    RETURNING id INTO v_word_id;
    IF NULLIF(v_item->>'part_of_speech', '') IS NOT NULL THEN
      INSERT INTO public.vocabulary_meanings (vocabulary_word_id, part_of_speech, meaning) VALUES (v_word_id, v_item->>'part_of_speech', v_item->>'meaning');
    END IF;
  END LOOP;
END; $$;
REVOKE ALL PRIVILEGES ON FUNCTION public.seed_default_vocabulary_pack_for_user(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.create_default_vocabulary_categories_for_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM public.seed_starter_vocabulary_for_user(NEW.id);
  PERFORM public.seed_default_vocabulary_pack_for_user(NEW.id);
  RETURN NEW;
END; $$;

-- Backfill only accounts that still have no vocabulary.
DO $$ DECLARE v_user_id uuid; BEGIN
  FOR v_user_id IN SELECT users.id FROM auth.users AS users WHERE NOT EXISTS (SELECT 1 FROM public.vocabulary_words AS words WHERE words.user_id = users.id) LOOP
    PERFORM public.seed_starter_vocabulary_for_user(v_user_id);
    PERFORM public.seed_default_vocabulary_pack_for_user(v_user_id);
  END LOOP;
END; $$;
